import java.util.*;

public class Solution {
    static List<List<Integer>> subconjuntos(int[] nums) {
        int[] a = nums.clone();
        Arrays.sort(a);
        List<List<Integer>> out = new ArrayList<>();
        explorar(a, 0, new ArrayList<>(), out);
        return out;
    }

    // Cada nó da recursão é um subconjunto. No mesmo nível, um valor igual ao anterior geraria repetição.
    private static void explorar(int[] a, int inicio, List<Integer> atual, List<List<Integer>> out) {
        out.add(new ArrayList<>(atual));
        for (int i = inicio; i < a.length; i++) {
            if (i > inicio && a[i] == a[i - 1]) continue;
            atual.add(a[i]);              // escolher
            explorar(a, i + 1, atual, out); // explorar
            atual.remove(atual.size() - 1); // desfazer
        }
    }
}

