public class Solution {
    static int contar(int n) {
        return colocar(0, n, new boolean[n], new boolean[2 * n], new boolean[2 * n]);
    }

    // Diagonal "/" tem linha + coluna constante; "\" tem linha − coluna + n constante.
    private static int colocar(int linha, int n, boolean[] col, boolean[] d1, boolean[] d2) {
        if (linha == n) return 1;
        int total = 0;
        for (int c = 0; c < n; c++) {
            if (col[c] || d1[linha + c] || d2[linha - c + n]) continue;
            col[c] = d1[linha + c] = d2[linha - c + n] = true;
            total += colocar(linha + 1, n, col, d1, d2);
            col[c] = d1[linha + c] = d2[linha - c + n] = false;
        }
        return total;
    }
}

